// Writes a set of generated files into a directory and keeps it in step: it
// creates missing files, rewrites a marked file that differs, refuses anything
// else that stands on an output path, and removes a marked file that is no
// longer produced.
//
// One directory holds the files of one target. The marker names no target, so
// two targets that share a directory and an extension would each remove the
// other's files as stale.
import fs from 'node:fs';
import path from 'node:path';

export const MARKER = '# Generated by scripts/gen-sprite-agents.mjs';

// A file counts as ours only if the marker is a line inside the leading
// frontmatter block (Markdown) or the first line (TOML). A marker further down
// is quoted text, such as a fenced example in a hand-written note.
export function isGenerated(file) {
  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch {
    return false;
  }
  // The BOM is stripped by hand because readFileSync keeps it as U+FEFF.
  const lines = text.replace(/^﻿/, '').split('\n').map((l) => l.replace(/\r$/, ''));
  if (lines[0] !== '---') return lines[0].startsWith(MARKER);
  const end = lines.indexOf('---', 1);
  return end !== -1 && lines.slice(1, end).some((l) => l.startsWith(MARKER));
}

// A key is a file name or `<dir>/<file>`, so one nesting level, and it must end
// in the extension: a key the listing cannot see would be rewritten on every run.
function checkKeys(outputs, ext) {
  for (const key of outputs.keys()) {
    const parts = key.split('/');
    const plain = parts.every((p) => p !== '' && p !== '.' && p !== '..');
    if (parts.length > 2 || !plain || !key.endsWith(ext)) {
      throw new Error(`output key ${JSON.stringify(key)} must be "<file>${ext}" or "<dir>/<file>${ext}" inside the output directory`);
    }
  }
}

// Every name one and two levels under outDir. A link is never followed into a
// directory and is never a file here, so a clean cannot reach through one.
function listEntries(outDir) {
  if (!fs.existsSync(outDir)) return [];
  const found = [];
  for (const entry of fs.readdirSync(outDir, { withFileTypes: true })) {
    found.push({ rel: entry.name, file: entry.isFile() });
    if (!entry.isDirectory()) continue;
    for (const inner of fs.readdirSync(path.join(outDir, entry.name), { withFileTypes: true })) {
      found.push({ rel: `${entry.name}/${inner.name}`, file: inner.isFile() });
    }
  }
  return found;
}

// What stands on an output path, judged without following a link. The out
// directory itself may be a link; only what is below it is looked at.
//   free:    nothing there yet
//   file:    a regular file, safe to read
//   link:    a link on the file or on a directory above it
//   blocked: a directory, a dangling link, or a file where a directory should be
function inspect(outDir, key) {
  const parts = key.split('/');
  let at = outDir;
  for (const [i, part] of parts.entries()) {
    at = path.join(at, part);
    let st;
    try {
      st = fs.lstatSync(at);
    } catch (e) {
      if (e.code === 'ENOENT') return 'free';
      throw e;
    }
    if (st.isSymbolicLink()) return fs.existsSync(at) ? 'link' : 'blocked';
    if (i === parts.length - 1 ? !st.isFile() : !st.isDirectory()) return 'blocked';
  }
  return 'file';
}

// `refused` lists every output path left untouched. `inTheWay` is the part of
// it where the cause is not a same-named file: a directory, a file standing
// where a directory is needed, or a dangling link.
export function syncDir(outDir, outputs, { check = false, ext = '.md' } = {}) {
  checkKeys(outputs, ext);
  const result = { written: [], removed: [], refused: [], inTheWay: [], drift: [] };
  const entries = listEntries(outDir);

  for (const [file, content] of outputs) {
    const full = path.join(outDir, file);
    const state = inspect(outDir, file);
    if (state === 'link') {
      result.refused.push(file);
    } else if (state === 'blocked') {
      result.refused.push(file);
      result.inTheWay.push(file);
    } else if (state === 'free') {
      // A filesystem that ignores case would write over a name that differs only by case.
      const sibling = entries.find((e) => e.rel.toLowerCase() === file.toLowerCase());
      if (sibling) result.refused.push(sibling.rel);
      else if (check) result.drift.push(`${file}: missing`);
      else {
        fs.mkdirSync(path.dirname(full), { recursive: true });
        fs.writeFileSync(full, content);
        result.written.push(file);
      }
    } else if (fs.readFileSync(full, 'utf8') !== content) {
      // A same-named file without the marker belongs to someone else.
      if (!isGenerated(full)) result.refused.push(file);
      else if (check) result.drift.push(`${file}: out of date`);
      else {
        fs.writeFileSync(full, content);
        result.written.push(file);
      }
    }
  }

  // A name that differs from an output only by case is never stale, it is refused above.
  const outputNames = new Set([...outputs.keys()].map((k) => k.toLowerCase()));
  for (const { rel: file, file: isFile } of entries) {
    if (!isFile || !file.endsWith(ext) || outputNames.has(file.toLowerCase()) || !isGenerated(path.join(outDir, file))) continue;
    if (check) result.drift.push(`${file}: stale, its sprite left the crew`);
    else {
      fs.rmSync(path.join(outDir, file));
      result.removed.push(file);
      const dir = path.dirname(path.join(outDir, file));
      if (file.includes('/') && fs.readdirSync(dir).length === 0) fs.rmdirSync(dir);
    }
  }
  return result;
}
